			zs_ba          => sd_ram_wire_ba,                                                --      .export
			zs_cas_n       => sd_ram_wire_cas_n,                                             --      .export
			zs_cke         => sd_ram_wire_cke,                                               --      .export
			zs_cs_n        => sd_ram_wire_cs_n,                                              --      .export
			zs_dq          => sd_ram_wire_dq,                                                --      .export
			zs_dqm         => sd_ram_wire_dqm,                                               --      .export
			zs_ras_n       => sd_ram_wire_ras_n,                                             --      .export
			zs_we_n        => sd_ram_wire_we_n                                               --      .export
		);

	reg16_component_0 : component reg16_avalon_interface
		port map (
			read       => reg16_component_0_avalon_slave_0_translator_avalon_anti_slave_0_read,       -- avalon_slave_0.read
			write      => reg16_component_0_avalon_slave_0_translator_avalon_anti_slave_0_write,      --               .write
			chipselect => reg16_component_0_avalon_slave_0_translator_avalon_anti_slave_0_chipselect, --               .chipselect
			writedata  => reg16_component_0_avalon_slave_0_translator_avalon_anti_slave_0_writedata,  --               .writedata
			byteenable => reg16_component_0_avalon_slave_0_translator_avalon_anti_slave_0_byteenable, --               .byteenable
			readdata   => reg16_component_0_avalon_slave_0_translator_avalon_anti_slave_0_readdata,   --               .readdata
			clock      => clk_clk,                                                                    --     clock_sink.clk
			resetn     => rst_controller_reset_out_reset_ports_inv,                                   --     reset_sink.reset_n
			Q_export   => to_hex_export                                                               --    conduit_end.export
		);

	pwm_component_0 : component pwm_avalon_interface
		port map (
			read         => pwm_component_0_avalon_slave_0_translator_avalon_anti_slave_0_read,       -- avalon_slave_0.read
			write        => pwm_component_0_avalon_slave_0_translator_avalon_anti_slave_0_write,      --               .write
			chipselect   => pwm_component_0_avalon_slave_0_translator_avalon_anti_slave_0_chipselect, --               .chipselect
