			readdata     => pwm_component_0_avalon_slave_0_translator_avalon_anti_slave_0_readdata,   --               .readdata
			clock        => clk_clk,                                                                  --     clock_sink.clk
			resetn       => rst_controller_reset_out_reset_ports_inv,                                 --     reset_sink.reset_n
			dc_motor_n_R => m_nr_export,                                                              --       motor_nR.export
			dc_motor_n_L => m_nl_export,                                                              --       motor_nL.export
			dc_motor_p_L => m_pl_export,                                                              --       motor_pL.export
			dc_motor_p_R => m_pr_export                                                               --       motor_pR.export
		);

