			ADC_SCK       => cpt_sol_SCK,                                                         --               .export
			ADC_SDI       => cpt_sol_SDI,                                                         --               .export
			ADC_SDO       => cpt_sol_SDO,                                                         --               .export
			clock         => clk_clk,                                                             --     clock_sink.clk
			resetn        => rst_controller_reset_out_reset_ports_inv,                            --     reset_sink.reset_n
			vect_capt_out => val_capt_export,                                                     --  conduit_end_1.export
			data_ready    => data_ready_export                                                    --  conduit_end_2.export
